-- Secondary independent six-model manufacturer intake.
-- Exact make+model+ID, no alias or prior staging, and zero public writes.
DO $$
DECLARE n integer; inserted integer; before_pub integer; after_pub integer;
BEGIN
 SELECT count(*) INTO before_pub FROM public.motorcycle_universal_published_sections_v1;
 WITH expected(id,make,model) AS (VALUES (208,'KTM','690 SMC R'),
(882,'KTM','690 Enduro R'),
(531,'KTM','RC 390'),
(5,'Aprilia','SX125'),
(243,'Triumph','SCRAMBLER 400 X'),
(244,'Triumph','SPEED 400'))
 SELECT count(*) INTO n FROM expected e
 JOIN public.motorcycle_catalog_models m ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.model
 WHERE NOT EXISTS (SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS (SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=e.id AND a.review_status<>'approved')
 AND EXISTS (SELECT 1 FROM public.motorcycle_catalog_manufacturers r WHERE r.display_name=e.make);
 IF n<>6 THEN RAISE EXCEPTION 'Secondary research identity/staging guard blocked (%)',n; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.slot,v.title,v.content,'draft','official_source_research:'||v.url,NULL
 FROM (VALUES (208,1,'Model introduction','{"summary":"The KTM 690 SMC R is a single-cylinder supermoto developed for road and track agility.","source_name":"KTM manufacturer source","source_url":"https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904'),
(208,7,'Documented model history and generation','{"summary":"KTM''s 1 February 2019 UK launch announcement confirms its revised 2019 model, including WP APEX suspension and two ride modes in that launch-year configuration.","source_name":"KTM manufacturer source","source_url":"https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904'),
(882,1,'Model introduction','{"summary":"KTM''s 690 Enduro R combines a large single-cylinder motorcycle platform with road and trail capability.","source_name":"KTM manufacturer source","source_url":"https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904'),
(882,7,'Documented model history and generation','{"summary":"KTM''s 1 February 2019 release confirms the 2019 690 Enduro R return alongside the separate SMC R, with model-specific off-road equipment.","source_name":"KTM manufacturer source","source_url":"https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://press.ktm.com/news-street-or-dirt-new-ktm-690-smc-r-ktm-690-enduro-r-released?id=78942&imageid=255889&l=uk&menueid=5904'),
(531,1,'Model introduction','{"summary":"The RC 390 is a compact single-cylinder sport motorcycle in KTM''s road-going RC range.","source_name":"KTM manufacturer source","source_url":"https://www.ktm.com/en-int/models/supersport/2024-ktm-rc-390/technical-specifications.html","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.ktm.com/en-int/models/supersport/2024-ktm-rc-390/technical-specifications.html'),
(531,7,'Documented model history and generation','{"summary":"KTM''s official 2024 RC 390 technical record lists a liquid-cooled 373 cc single, six-speed transmission, steel trellis chassis and 13.7-litre tank for that specific model year.","source_name":"KTM manufacturer source","source_url":"https://www.ktm.com/en-int/models/supersport/2024-ktm-rc-390/technical-specifications.html","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.ktm.com/en-int/models/supersport/2024-ktm-rc-390/technical-specifications.html'),
(5,1,'Model introduction','{"summary":"Aprilia''s SX 125 is a small-capacity motard-style road motorcycle within Aprilia''s 125 family.","source_name":"Aprilia manufacturer source","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(5,7,'Documented model history and generation','{"summary":"Aprilia''s March 2022 range announcement lists three SX 125 colour schemes for that model year; RX 125 enduro variants and GP Replica RS 125 equipment must remain distinct.","source_name":"Aprilia manufacturer source","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(243,1,'Model introduction','{"summary":"Triumph''s Scrambler 400 X is a small-capacity road-and-light-adventure styled motorcycle sharing a new single-cylinder platform with the Speed 400.","source_name":"Triumph manufacturer source","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13'),
(243,7,'Documented model history and generation','{"summary":"Triumph''s October 2023 UK price and introduction announcement anticipated Scrambler 400 X dealer arrivals from late January 2024. These dates describe the UK, not every market.","source_name":"Triumph manufacturer source","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13'),
(244,1,'Model introduction','{"summary":"Triumph''s Speed 400 is a compact roadster developed alongside the Scrambler 400 X on a new single-cylinder platform.","source_name":"Triumph manufacturer source","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13'),
(244,7,'Documented model history and generation','{"summary":"Triumph introduced the Speed 400 in 2023, announcing UK dealer availability from late January 2024. Its UK release is not proof of identical launch dates worldwide.","source_name":"Triumph manufacturer source","source_url":"https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Research-only exact model/year source note. Verify before public use; no publication or image approval."}'::jsonb,'https://www.triumphmotorcycles.co.uk/for-the-ride/news/classics/trseries-price-reveal-2023-10-13')) v(model_id,slot,title,content,url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>12 THEN RAISE EXCEPTION 'Expected 12 research drafts got %',inserted; END IF;
 SELECT count(*) INTO after_pub FROM public.motorcycle_universal_published_sections_v1;
 IF before_pub<>after_pub THEN RAISE EXCEPTION 'Public projection changed'; END IF;
END $$;
